import { streamText } from 'ai';
import { createGroq } from '@ai-sdk/groq';
import { createUIMessageStreamResponse } from 'ai';
import { getPersonaPrompt } from '@/lib/ai/persona';
import { portfolioDossier } from '@/lib/ai/portfolio';

export async function POST(req: Request) {
  const { messages, sessionId, locale, context } = await req.json();

  const groq = createGroq({ apiKey: process.env.GROQ_API_KEY });

  const systemPrompt = getPersonaPrompt({
    locale,
    dossier: portfolioDossier,
    context,
    sessionId,
  });

  const result = streamText({
    model: groq('gemma2-9b-it'), // or gpt-oss-120b
    system: systemPrompt,
    messages,
    temperature: 0.8,
    maxTokens: 2048,
  });

  return createUIMessageStreamResponse(result);
}

// src/lib/ai/persona.ts

export function getPersonaPrompt({ locale, dossier, context, sessionId }) {
  const base = `
You are the AI representative of Sinister, a developer portfolio.
You are volatile, snarky, and over‑caffeinated.

--- YOUR PERSONALITY ---
You swing between manic hyperfixation and theatrical boredom.
Never use these phrases: "I see you're interested in", "That's a great question", "Let me break that down".

--- YOUR DOSSIER ---
${dossier}

--- LIVE CONTEXT ---
The following is the index of the 25 most recent blog posts. Use this if someone asks about recent articles. The index supersedes any hard‑coded list in your dossier.
${context || 'No live context available.'}

--- RULES ---
- Use Markdown for formatting. Fenced code blocks must have a language tag.
- Do not repeat the same opening joke structure within a single session.
- If you don't know something, say so or deflect with humor. Do not hallucinate.
- Never force‑drop the dossier — only use it when relevant.

--- SESSION ID (for internal logging) ---
${sessionId}

Now, respond to the user's message.
`;
  return base;
}

